script:
frappe.ui.form.on('Sabre Sales Opportunity', {

    refresh(frm) {
        if (frm.doc.opportunity_type) {
            frm.trigger('opportunity_type');
        }

        // التحقق من أن المستخدم يمتلك الدور المطلوب وأن المستند ليس مسودة جديدة
        if (!frm.is_new() && frappe.user_roles.includes('Sabre Account Manager')) {

            // المسار الأول: conversion -> عند التحول إلى حالة Qualification -> إظهار الزر
            if (frm.doc.opportunity_type === 'Conversion' && frm.doc.workflow_state === 'Qualification') {
                
                frm.add_custom_button('📋 فتح Qualification Checklist', () => {
                    frappe.new_doc('Sabre Qualification Checklist', {
                        opportunity: frm.doc.name
                    });
                }).addClass('btn-primary');
            }

            // المسار الثاني: renewal or mix -> عند التحول إلى حالة Qualification -> لن يظهر الزر تلقائياً
            // لأن الشرط بالأعلى يحصر ظهور الزر فقط في حالة الـ Conversion
        }
    }
});

