    // ne_percentage(frm) { frm.trigger('check_airline_mix'); },
    // other_percentage(frm) { frm.trigger('check_airline_mix'); },

    // check_airline_mix(frm) {
    //     let total = (frm.doc.ms_percentage || 0) +
    //                 (frm.doc.sv_percentage || 0) +
    //                 (frm.doc.ek_percentage || 0) +
    //                 (frm.doc.np_percentage || 0) +
    //                 (frm.doc.ne_percentage || 0) +
    //                 (frm.doc.other_percentage || 0);

    //     if (total > 100) {
    //         frappe.show_alert({
    //             message: `⚠️ مجموع Airline Mix = ${total}% — يجب أن لا يتجاوز 100%`,
    //             indicator: 'red'
    //         });
    //     } else if (total === 100) {
    //         frappe.show_alert({
    //             message: `✅ مجموع Airline Mix = 100%`,
    //             indicator: 'green'
    //         });
    //     } else {
    //         frappe.show_alert({
    //             message: `📊 مجموع Airline Mix = ${total}%`,
    //             indicator: 'orange'
    //         });
    //     }
    // },

    // عند تغيير نتيجة التأهيل
    qualified(frm) {
        if (frm.doc.qualified === 'No') {
            frm.toggle_display('reason_code', true);
            frm.set_df_property('reason_code', 'reqd', 1);
        } else {
            frm.toggle_display('reason_code', false);
            frm.set_df_property('reason_code', 'reqd', 0);
            frm.set_value('reason_code', '');
        }
    }

});

frappe.ui.form.on('Sabre Business Case', {

    // عند فتح الفورم
    refresh(frm) {
        frm.toggle_display('head_of_sales_notes', false);

        if (frm.doc.status) {
            frm.trigger('status');
        }
    },

    // جلب بيانات الـ Opportunity تلقائياً
    opportunity(frm) {
    if (frm.doc.opportunity) {
        frappe.db.get_value(
            'Sabre Sales Opportunity',
            frm.doc.opportunity,
            ['customer', 'pipeline_am', 'airline_mix', 'yoy_review'],
            (data) => {
                if (data) {
                    frm.set_value('customer', data.customer);
                    frm.set_value('pipeline_am', data.pipeline_am);
                    frm.set_value('airline_mix', data.airline_mix);
                    frm.set_value('yoy_review', data.yoy_review);
                }
            }
        );
    }
},

    // إظهار Head of Sales Notes عند Rejected فقط
    status(frm) {
        if (frm.doc.status === 'Rejected') {
            frm.toggle_display('head_of_sales_notes', true);
            frm.set_df_property('head_of_sales_notes', 'reqd', 1);
        } else {
            frm.toggle_display('head_of_sales_notes', false);
            frm.set_df_property('head_of_sales_notes', 'reqd', 0);
        }
    }

});

frappe.ui.form.on('Sabre Contract', {

    // عند فتح الفورم
    refresh(frm) {
        frm.toggle_display('notes', false);

        if (frm.doc.head_of_sales_review) {
            frm.trigger('head_of_sales_review');
        }
    },

    // جلب بيانات الـ Opportunity تلقائياً
    opportunity(frm) {
        if (frm.doc.opportunity) {
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am'],
                (data) => {
                    if (data) {
                        frm.set_value('customer', data.customer);
                        frm.set_value('pipeline_am', data.pipeline_am);
                    }
                }
            );
        }
    },

    // إظهار Notes عند Rejected فقط
    head_of_sales_review(frm) {
        if (frm.doc.head_of_sales_review === 'Rejected') {
            frm.toggle_display('notes', true);
            frm.set_df_property('notes', 'reqd', 1);
        } else {
            frm.toggle_display('notes', false);
            frm.set_df_property('notes', 'reqd', 0);
        }
    }

});

frappe.ui.form.on('Sabre Implementation', {

    // عند فتح الفورم
    refresh(frm) {
        // إظهار زر إنشاء Ticket تلقائياً
        if (!frm.doc.ticket_number && !frm.is_new()) {
            frm.add_custom_button('إنشاء Ticket', () => {
                frappe.prompt(
                    { label: 'رقم الـ Ticket', fieldname: 'ticket', fieldtype: 'Data' },
                    (values) => {
                        frm.set_value('ticket_number', values.ticket);
                        frm.save();
                        frappe.show_alert({
                            message: `✅ تم حفظ رقم الـ Ticket: ${values.ticket}`,
                            indicator: 'green'
                        });
                    },
                    'إنشاء Ticket',
                    'حفظ'
                );
            });
        }
    },

    // جلب بيانات الـ Opportunity تلقائياً
    opportunity(frm) {
        if (frm.doc.opportunity) {
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am'],
                (data) => {
                    if (data) {
                        frm.set_value('customer', data.customer);
                        frm.set_value('pipeline_am', data.pipeline_am);
                    }
                }
            );
        }
    },

    // تنبيه عند تغيير Status
    status(frm) {
        if (frm.doc.status === 'Completed') {
            frappe.show_alert({
                message: '✅ ممتاز! سيتم تحريك الفرصة إلى Go-Live بعد الحفظ',
                indicator: 'green'
            });
        } else if (frm.doc.status === 'On Hold') {
            frappe.show_alert({
                message: '⏸️ تم تعليق التنفيذ',
                indicator: 'orange'
            });
        }
    }

});

frappe.ui.form.on('Sabre Go-Live', {
    refresh(frm) {
        if (frm.doc.status === 'Active' && !frm.is_new()) {
            frm.add_custom_button('🏆 Mark Won', () => {
                frappe.confirm(
                    'هل أنت متأكد من إغلاق الفرصة كـ Won؟',
                    () => {
                        frappe.db.set_value(
                            'Sabre Sales Opportunity',
                            frm.doc.opportunity,
                            'workflow_state',
                            'Closed - Won'
                        ).then(() => {
                            frappe.show_alert({
                                message: '🏆 تم إغلاق الفرصة كـ Closed - Won',
                                indicator: 'green'
                            });
                            frm.reload_doc();
                        });
                    }
                );
            }).addClass('btn-success');
        }
        if (frm.doc.follow_up_30_days) {
            frappe.show_alert({
                message: `📅 متابعة 30 يوم: ${frm.doc.follow_up_30_days}`,
                indicator: 'blue'
            });
        }
    },
    opportunity(frm) {
        if (frm.doc.opportunity) {
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am'],
                (data) => {
                    if (data) {
                        frm.set_value('customer', data.customer);
                        frm.set_value('pipeline_am', data.pipeline_am);
                    }
                }
            );
        }
    },
    status(frm) {
        if (frm.doc.status === 'Won') {
            frappe.show_alert({
                message: '🏆 ممتاز! سيتم إغلاق الفرصة كـ Closed - Won',
                indicator: 'green'
            });
        } else if (frm.doc.status === 'Issues') {
            frappe.show_alert({
                message: '⚠️ سيتم إعادة الفرصة إلى Implementation',
                indicator: 'orange'
            });
        } else if (frm.doc.status === 'Active') {
        frappe.show_alert({
            message: '🚀 الفرصة في مرحلة Go-Live',
            indicator: 'blue'
            });
        }
    },
    go_live_date(frm) {
        if (frm.doc.go_live_date) {
            frappe.show_alert({
                message: '📅 سيتم حساب تواريخ المتابعة تلقائياً عند الحفظ',
                indicator: 'blue'
            });
        }
    }
});
